def binary_crossentropy(target, output, from_logits=False):
    if from_logits:
        return np.mean(-target * output + np.log(1 + np.exp(output)))
    else:
        output = np.clip(output, 1e-7, 1 - 1e-7)
        return np.mean(-target * np.log(output) - (1 - target) * np.log(1 - output))
```
